const generationMethods={random:'均匀随机',hot:'热号加权',cold:'冷号加权',tree:'树模型',lstm:'LSTM'};
const structureNames={singles:'分散单式',compound:'复式',dantuo:'4 胆 6 拖 / 后区 3 个'};
state.genConfig={method:'random',target:'26124',budget:36,window:60,structure:'singles',front:6,back:3,additional:false,seed:20261029};
state.generated=null;state.genDirty=false;state.genError='';
function generation(){const p=state.genConfig,blocked=['tree','lstm'].includes(p.method);return heading('方案生成','固定方法、目标期和预算，生成候选组合，再与随机对照一起评估。',go('返回方法与模型','training'))+`
<div class="two-column generation-layout"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>生成设置</h2><p>候选方案不自动形成采用建议</p></div>${tag(blocked?'权重未就绪':'可生成',blocked?'amber':'blue')}</div><form id="generation-form" class="panel-body"><div class="form-row"><div class="field"><label for="gen-method">方法版本</label><select id="gen-method" name="method">${Object.entries(generationMethods).map(([k,v])=>`<option value="${k}" ${p.method===k?'selected':''}>${v} / ${['tree','lstm'].includes(k)?'待接入权重':'v1'}</option>`).join('')}</select></div><div class="field"><label for="gen-target">目标期</label><input id="gen-target" name="target" value="${escape(p.target)}" required pattern="[0-9]{5}"><small>数据截至 ${D.issue} 期，当前支持下一目标期 26124。</small></div></div><div class="form-row"><div class="field"><label for="gen-budget">预算上限（元）</label><input id="gen-budget" name="budget" type="number" min="2" max="360" step="1" value="${p.budget}" required></div><div class="field"><label for="gen-structure">组合结构</label><select id="gen-structure" name="structure">${Object.entries(structureNames).map(([k,v])=>`<option value="${k}" ${p.structure===k?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="form-row" ${p.structure==='compound'?'':'hidden'}><div class="field"><label for="gen-front">复式前区数量</label><input id="gen-front" name="front" type="number" min="5" max="10" value="${p.front}" required></div><div class="field"><label for="gen-back">复式后区数量</label><input id="gen-back" name="back" type="number" min="2" max="5" value="${p.back}" required></div></div><div class="form-row"><div class="field"><label for="gen-window">历史窗口</label><select id="gen-window" name="window"><option value="60" ${p.window===60?'selected':''}>60 期</option><option value="120" ${p.window===120?'selected':''}>120 期</option></select></div><div class="field"><label for="gen-seed">随机种子</label><input id="gen-seed" name="seed" type="number" min="0" max="4294967295" value="${p.seed}" required></div></div><label class="checkbox-row"><input name="additional" id="gen-additional" type="checkbox" ${p.additional?'checked':''}><span>追加投注，每注成本 3 元</span></label>${blocked?'<div class="notice amber">当前模型没有可用于推理的权重。请选择可用方法，或先完成真实模型训练与版本核验。</div>':''}<div id="gen-error" class="error-text" role="alert">${escape(state.genError)}</div><div class="inline-form-actions"><button class="button primary" type="submit" ${blocked?'disabled':''}>${icon('play')}生成候选方案</button></div></form></section><section id="generation-results" aria-live="polite">${generationResults()}</section></div><aside class="stack"><section class="panel"><div class="panel-head"><h2>采用依据</h2>${tag('证据不足','amber')}</div><div class="panel-body"><h3>暂无证据支持优先采用</h3><p class="section-subtext">当前生成结果用于研究比较，尚未通过独立回测与前瞻验证。</p><ul class="check-list">${['号码、成本和去重检查','同预算、同结构随机对照','独立回测：待开展','前瞻验证：待积累'].map((t,i)=>`<li>${icon(i<2?'check':'clock')}<span>${t}</span></li>`).join('')}</ul></div></section><section class="notice">热号权重为历史频次 + 1；冷号权重为其倒数。均为无放回加权抽样假设，不将号码评分显示为中奖概率。</section></aside></div>`;}
function readGeneration(){const f=new FormData(el('generation-form'));return {method:f.get('method'),target:f.get('target'),budget:Number(f.get('budget')),window:Number(f.get('window')),structure:f.get('structure'),front:Number(f.get('front')),back:Number(f.get('back')),additional:f.get('additional')==='on',seed:Number(f.get('seed'))};}
function openGeneration(method='random'){state.genConfig={...state.genConfig,method};state.genDirty=!!state.generated;state.genError='';navigate('generation');}
function generateCandidates(){state.genConfig=readGeneration();try{const result=window.generateDltCandidates({...state.genConfig,cutoff:D.issue},D.generationHistory);result.createdAt=new Date().toISOString();result.historySha256=D.generationHistorySha256;state.generated=result;state.genDirty=false;state.genError='';el('main').innerHTML=generation();el('gen-error').textContent='';el('generation-results').scrollIntoView({block:'start',behavior:'instant'});}catch(e){state.genError=e.message;el('gen-error').textContent=e.message;}}
function portfolioTickets(plan,label){return `<details class="portfolio-tickets"><summary>查看${label}全部 ${plan.count} 注</summary><ol>${plan.tickets.map(t=>`<li><span class="ball-row">${t.front.map(n=>`<span class="ball">${String(n).padStart(2,'0')}</span>`).join('')}<span class="ticket-divider">+</span>${t.back.map(n=>`<span class="ball back">${String(n).padStart(2,'0')}</span>`).join('')}</span></li>`).join('')}</ol></details>`;}
function generationResults(){const r=state.generated;if(!r||state.genDirty)return `<div class="panel calculation-empty"><span class="calculation-state-dot"></span><div><h3>${state.genDirty?'设置已变更，请重新生成':'等待生成候选方案'}</h3><p>生成后查看候选组合、实际成本与匹配的随机对照。</p></div></div>`;
const p=r.parameters;return `<section class="panel"><div class="panel-head"><div><h2>候选与随机对照</h2><p>${generationMethods[p.method]} / ${structureNames[p.structure]} / 第 ${escape(p.target)} 期</p></div>${tag('待评估','amber')}</div><div class="panel-body"><div class="notice">两组方案使用相同预算与组合结构；当前没有独立评估结果，不作优劣排名。</div><div class="table-wrap section-space"><table class="data-table"><thead><tr><th>方案</th><th class="align-right">注数</th><th class="align-right">实际成本</th><th class="align-right">预算余额</th><th>前 / 后区号码覆盖</th></tr></thead><tbody>${[[r.candidate,'候选方案'],[r.control,'随机对照']].map(([x,label])=>`<tr><td>${label}<small>${label==='候选方案'?generationMethods[p.method]:'均匀随机 / 独立种子'}</small></td><td class="align-right">${x.count}</td><td class="align-right">${x.cost} 元</td><td class="align-right">${x.remaining} 元</td><td>${x.frontCoverage} / ${x.backCoverage}<small>覆盖数量不代表中奖概率</small></td></tr>`).join('')}</tbody></table></div><div class="two-equal section-space">${[[r.candidate,'候选'],[r.control,'对照']].map(([x,label])=>`<div class="portfolio-detail"><h3>${label}组合</h3><p class="section-subtext">种子 ${x.seed}${x.pool?` / ${x.pool.dan?'胆 '+x.pool.dan.join('、')+'；拖 '+x.pool.drag.join('、'):'前区 '+x.pool.front.join('、')} / 后区 ${x.pool.back.join('、')}`:''}</p>${portfolioTickets(x,label)}</div>`).join('')}</div><details class="generation-provenance section-space"><summary>生成依据与版本</summary><dl class="definition-list section-space"><div><dt>生成器 / 方法版本</dt><dd>${r.version} / ${r.methodVersion}</dd></div><div><dt>历史窗口</dt><dd>${r.history.first}—${r.history.last} / ${r.history.count} 期</dd></div><div><dt>生成时间</dt><dd>${new Date(r.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}（北京时间）</dd></div><div><dt>历史快照摘要</dt><dd class="mono">${r.historySha256}</dd></div></dl></details><div class="inline-form-actions">${button('登记为实验草稿','generated-experiment','primary')}</div></div></section>`;}
function generatedWizard(step=1){const w=state.wizard,r=w.generated,p=r.parameters;w.step=step;let content='';
if(step===1)content=`<form id="generated-first"><div class="field"><label for="generated-exp-name">实验名称</label><input id="generated-exp-name" name="name" value="${escape(w.name)}" required maxlength="60"></div>${line('来源方法',generationMethods[p.method]+' / '+r.methodVersion)}${line('目标期',escape(p.target))}${line('组合结构',structureNames[p.structure])}${line('实际成本',r.candidate.cost+' 元 / 每方案')}${line('组合包','候选与对照各 1 份')}<p class="section-subtext">保留本次生成的具体号码和参数，不在登记时重新抽取。</p><div class="inline-form-actions">${button('取消','close-experiment')}<button class="button primary" type="submit">下一步：匹配对照</button></div></form>`;
else if(step===2)content=`<h3>核对公平对照</h3>${line('候选方法',generationMethods[p.method])}${line('随机对照','均匀随机 / '+structureNames[p.structure])}${line('实际投入',r.candidate.cost+' 元 = '+r.control.cost+' 元')}${line('基本组合',r.candidate.count+' 注 = '+r.control.count+' 注')}<div class="notice section-space">两份组合包共享同一目标期开奖，不能视为两个独立奖期。当前评估状态：待评估。</div><div class="inline-form-actions">${button('上一步','wizard-back')}${button('下一步：复核草稿','wizard-next','primary')}</div>`;
else content=`<h3>${escape(w.name)}</h3>${line('目标期',escape(p.target))}${line('历史窗口',r.history.first+'—'+r.history.last)}${line('实际成本 / 预算',r.candidate.cost+' / '+p.budget+' 元')}${line('记录内容','方法版本、参数、候选与对照全部号码')}${line('状态','未封存 / 待评估')}<div class="notice section-space">保存到当前会话，与原有封存记录独立管理。</div><div class="inline-form-actions">${button('上一步','wizard-back')}${button('保存草稿','save-draft','primary')}</div>`;
if(state.page!=='prospective')navigate('prospective');const editor=el('experiment-editor');editor.hidden=false;editor.innerHTML=`<div class="panel-head"><div><h2 id="experiment-editor-title" tabindex="-1">登记候选方案</h2><p>固定生成结果，核对对照后保存。</p></div>${button('取消创建','close-experiment')}</div><div class="panel-body generated-review"><div class="wizard-steps">${['定义实验','匹配对照','复核草稿'].map((v,i)=>`<span class="${step===i+1?'current':''}" ${step===i+1?'aria-current="step"':''}>${i+1}. ${v}</span>`).join('')}</div>${content}</div>`;(step===1?el('generated-exp-name'):el('experiment-editor-title')).focus({preventScroll:true});editor.scrollIntoView({block:'start',behavior:'instant'});}
